const fs=require('fs');const path=require('path');const ROOT=path.resolve(__dirname,'..');const MARK='CE_DATA_WAVE1D_20260809';
function insert(rel,anchor,block){const p=path.join(ROOT,rel);let s=fs.readFileSync(p,'utf8');if(s.includes(MARK+':'+rel))return false;if(!s.includes(anchor))throw new Error(`Ancre introuvable ${rel}`);s=s.replace(anchor,`<!-- ${MARK}:${rel} -->\n${block}\n${anchor}`);fs.writeFileSync(p,s,'utf8');return true;}

insert('articles/comparatif-produits-bancaires.html','<h2>1. Commencer par la date où l’argent peut être nécessaire</h2>',`<div class="case-study" id="marche-epargne-2026"><h2>Compte à terme et fonds en euros : deux repères de marché réels</h2><p><strong>Les périodes ne sont pas identiques : ce tableau informe, il ne classe pas.</strong> En mai 2026, la Banque de France mesure à <strong>2,23 % brut</strong> le taux moyen des nouveaux dépôts à terme de ménages d'une durée inférieure ou égale à deux ans. Pour l'assurance-vie, l'ACPR mesure un taux moyen de revalorisation des supports euros individuels de <strong>2,63 % en 2025</strong>, net des prélèvements sur encours et avant prélèvements sociaux.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Repère observé</th><th>Taux</th><th>10 000 € sur un an</th><th>Ce que le chiffre ne dit pas</th></tr></thead><tbody><tr><td>Nouveau dépôt à terme ≤ 2 ans · ménages · mai 2026</td><td><strong>2,23 % brut</strong></td><td>223 € brut</td><td>Chaque banque fixe son offre ; retrait anticipé et fiscalité peuvent modifier le résultat.</td></tr><tr><td>Fonds en euros individuels · moyenne 2025</td><td><strong>2,63 %</strong></td><td>263 € avant prélèvements sociaux</td><td>C'est une moyenne passée : taux 2026 inconnu, contrats et bonifications très dispersés.</td></tr></tbody></table></div><p>L'ACPR indique par ailleurs un <strong>taux moyen de chargement de gestion de 0,63 %</strong> sur les contrats individuels en 2025. Les mécanismes de bonification peuvent créer des écarts d'au moins 0,4 point autour du taux moyen : un « fonds euros à X % » doit donc être lu avec les conditions de l'offre et du contrat.</p><p class="source-note">Sources observées : <a href="https://www.banque-france.fr/fr/statistiques/epargne/taux-de-remuneration-des-depots-bancaires-2026-05" rel="noopener noreferrer">Banque de France — dépôts bancaires, mai 2026</a> ; <a href="https://acpr.banque-france.fr/en/node/1922312" rel="noopener noreferrer">ACPR — Revalorisation 2025 des contrats d'assurance-vie et de capitalisation, n°180</a>.</p></div>`);

insert('articles/tester-metier-avant-investir.html','<h2>3. Observer les « mauvais moments » du métier</h2>',`<div class="case-study" id="marche-travail-2026"><h2>Le marché 2026 en chiffres : il faut regarder le métier ET le territoire</h2><p><strong>Donnée France Travail, enquête BMO 2026.</strong> Les employeurs déclarent environ <strong>2,3 millions de projets de recrutement</strong> en France en 2026, en baisse de <strong>6,5 %</strong> sur un an. <strong>43,8 %</strong> des projets sont jugés difficiles par les employeurs.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Indicateur national</th><th>2026</th><th>Ce qu'il faut en faire</th></tr></thead><tbody><tr><td>Projets de recrutement</td><td><strong>≈ 2,3 millions</strong></td><td>Mesure l'intention déclarée des employeurs, pas un nombre garanti d'embauches.</td></tr><tr><td>Évolution vs 2025</td><td><strong>-6,5 %</strong></td><td>Le marché global ralentit : la sélection du secteur et de la zone compte davantage.</td></tr><tr><td>Recrutements jugés difficiles</td><td><strong>43,8 %</strong></td><td>Une tension peut signaler une opportunité, mais aussi des contraintes fortes ou un manque de profils adaptés.</td></tr></tbody></table></div><p>Le chiffre national ne suffit donc pas à valider une reconversion. Le test utile consiste à descendre au <strong>métier précis, au bassin d'emploi accessible, au type de contrat et au salaire d'entrée</strong>. Une formation peut viser un métier « en tension » au niveau national et rester peu pertinente dans votre zone.</p><p class="source-note">Source : <a href="https://statistiques.francetravail.org/bmo/bmopub?year=2026" rel="noopener noreferrer">France Travail — Besoins en main-d'œuvre 2026</a>, publiée le 21 avril 2026.</p></div>`);

insert('dossiers/experience-devient-risque-recruteur.html','<h2>2. Les risques perçus à traiter</h2>',`<div class="case-study" id="emploi-seniors-2025"><h2>Après 50 ans : les chiffres montrent une présence accrue dans l'emploi, pas une disparition du risque de recrutement</h2><p><strong>Données Insee 2025.</strong> Le taux d'emploi des <strong>50–64 ans atteint 69,2 %</strong>, en hausse de 0,9 point sur l'année. Chez les <strong>60–64 ans, il atteint 44,4 %</strong>, soit +2 points en un an. Les 50 ans ou plus représentent désormais <strong>32,8 % des personnes en emploi</strong>, contre 31,7 % en 2020.</p><div class="compare-wrap"><table class="compare-table"><thead><tr><th>Repère</th><th>2025</th><th>Lecture correcte</th></tr></thead><tbody><tr><td>Taux d'emploi 50–64 ans</td><td><strong>69,2 %</strong></td><td>La présence des seniors dans l'emploi progresse fortement à long terme.</td></tr><tr><td>Taux d'emploi 60–64 ans</td><td><strong>44,4 %</strong></td><td>L'emploi augmente aussi aux âges proches de la retraite.</td></tr><tr><td>Part des 50 ans ou plus parmi les personnes en emploi</td><td><strong>32,8 %</strong></td><td>Un actif en emploi sur trois environ a au moins 50 ans.</td></tr></tbody></table></div><p><strong>Attention à l'interprétation :</strong> un taux d'emploi n'est pas une probabilité d'être recruté après une candidature. Ces données ne mesurent ni discrimination, ni durée de recherche, ni risque individuel. Elles montrent toutefois que « senior = hors du marché » est factuellement faux ; le dossier reste centré sur la manière de rendre une candidature expérimentée crédible pour un poste précis.</p><p class="source-note">Source : <a href="https://www.insee.fr/fr/statistiques/8733041?sommaire=8733125" rel="noopener noreferrer">Insee — Caractéristiques des personnes en emploi, données 2025</a>, publié en 2026.</p></div>`);

