const ap=path.join(ROOT,'editorial/audit-chiffrage-bibliotheque.md');let a=fs.readFileSync(ap,'utf8');a=a.replace('Reste à documenter davantage comptes à terme et fonds euros.','Comptes à terme et fonds euros ajoutés le 9 août 2026 à partir de la Banque de France et de l’ACPR.');a=a.replace('- `articles/tester-metier-avant-investir.html` — salaires d’entrée, volumes d’offres, tension du métier, durée/coût des formations.','- `articles/tester-metier-avant-investir.html` — **enrichi le 9 août 2026** avec BMO France Travail 2026 (volume et difficultés de recrutement). Reste à ajouter salaires d’entrée et données métier/locales dans les dossiers sectoriels.');a=a.replace('- `dossiers/experience-devient-risque-recruteur.html` — taux d’emploi par âge, durée de chômage, écarts de recrutement seniors.','- `dossiers/experience-devient-risque-recruteur.html` — **enrichi le 9 août 2026** avec taux d’emploi Insee 2025 des 50–64 et 60–64 ans. Reste à documenter durée de recherche et écarts de recrutement avec sources robustes.');fs.writeFileSync(ap,a,'utf8');console.log('Wave 1d appliquée.');